import{_ as i,a0 as s,w as n,s as o,ao as f,I as d,x as e,a1 as a,A as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const h=JSON.parse('{"title":"為什麼企業應該選擇平台即服務（PaaS） | LCTT x X-CMD","titleTemplate":false,"description":"為什麼企業應該選擇平台即服務（PaaS） | LCTT (202302) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"為什麼企業應該選擇平台即服務（PaaS） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"為什麼企業應該選擇平台即服務（PaaS） | LCTT (202302) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202302/20220914 Why Enterprises Should  Opt for Platform as a Service","title":"為什麼企業應該選擇平台即服務（PaaS）","tag":"202302","desc":""},"relativePath":"202302/20220914 Why Enterprises Should  Opt for Platform as a Service.md","filePath":"[post].md"}'),p={name:"202302/20220914 Why Enterprises Should  Opt for Platform as a Service.md"};function y(g,t,u,x,S,P){const l=s("Link");return n(),o("div",null,[t[15]||(t[15]=f('<h1 id="為什麼企業應該選擇平台即服務-paas" tabindex="-1">為什麼企業應該選擇平台即服務（PaaS） <a class="header-anchor" href="#為什麼企業應該選擇平台即服務-paas" aria-label="Permalink to “為什麼企業應該選擇平台即服務（PaaS）”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202302/17/094352atasztuxqg4t1ctt.jpg" alt=""></p><blockquote><p>平台即服務能夠快速、輕鬆地創建網絡應用，而無需購買和維護其下的軟件和基礎設施。本文解釋了它為什麼有用。</p></blockquote><p><ruby>平台即服務<rt>PaaS</rt></ruby>（以下簡稱 PaaS）指的是雲計算服務，它為客户提供了開發、運行和管理應用程序的平台，而免去了建立和維護與開發和啓動應用程序相關的基礎設施的複雜工作。這是雲原生應用和支持系統所依託的核心平台。</p><p>PaaS 通常包括不同的應用基礎功能，包括應用平台、集成平台、業務分析平台、事件流服務和移動後端服務。此外，它還包括一套與監控、管理、部署相關的功能。</p><p>開發人員希望他們的開發環境不需要等待，而運營團隊則更關心性能和穩定性。這經常引起兩方間的衝突。PaaS 為這兩方創造了和平的環境。一個作為服務交付的應用平台被稱作 PaaS，它被用於部署用户代碼。Cloud Foundry、Cloudify 和 OpenShift 這些開源環境都可用作 PaaS。</p><h3 id="paas-的採用模式" tabindex="-1">PaaS 的採用模式 <a class="header-anchor" href="#paas-的採用模式" aria-label="Permalink to “PaaS 的採用模式”">​</a></h3><p>雲計算必須滿足五個基本特徵：按需服務、接入網絡、資源池化、彈性和可度量的服務。為此，雲計算提供了三種服務模式：<ruby>軟件即服務<rt>Software as a Service</rt></ruby>（SaaS）、<ruby>平台即服務<rt>Platform as a Service</rt></ruby>（PaaS）、<ruby>基礎設施即服務<rt>Infrastructure as a Service</rt></ruby>（IaaS）。</p><p>業務選用 PaaS 的關鍵驅動力：</p><ul><li>減少提供業務的資本支出和運營費用</li><li>通過減少應用程序的交付時間和提高開發和交付質量，最大限度地降低 IT 成本</li><li>增加中間件之間的靈活性和集成度</li></ul><p><em>簡單 PaaS</em>：踏入 PaaS 領域的入口。它可以提供應用程序服務，並將它們暴露在自助服務的目錄中；自動部署和計量服務使用的資源。</p><p><em>管理 PaaS</em>：管理已配置應用程序的<ruby>服務級別協議<rt>SLA</rt></ruby>和<ruby>服務質量<rt>QoS</rt></ruby>，例如彈性、應用程序性能、安全性等。</p><p><em>編程 PaaS</em>：允許應用程序與外部應用程序或公共雲集成，並實現自動擴展和雲爆發場景。</p><p><em>面向流程 PaaS</em>：允許通過創建持續交付流程來實現<ruby>開發運維<rt>DevOps</rt></ruby>流程，該流程可以自動構建、測試應用程序並將其交付到雲環境中。</p><p>除了這些採用模式之外，還有其他的 PaaS 變體如下，這些變化可能與上文的模式有一定重合：</p><p><em>集成平台即服務（iPaaS）</em>：一套能夠開發、執行和管理集成流的雲服務。集成流可以是個人內部或跨多個組織連接的，可以包含任何企業內部或基於雲的流程、服務、應用和數據。這些組合變化可能也符合上述的模式之一，例如 MuleSoft CloudHub 和 BizTalk。</p><p><em>移動平台即服務（mPaaS）</em>：為開發移動應用提供的集成開發環境（IDE），並且支持多種移動平台。</p><p><em>資料庫平台即服務（dbPaas）</em>：一種按需的、安全且可擴展的自助式資料庫平台，可自動配置和管理資料庫。dbPaaS 使擴展資料庫變得更加容易，並使它們更加可靠。</p><p><em>物聯網平台即服務（IoTPaaS）</em>：提供了實現異構物聯網拓撲所需的通信、安全、分析和管理的通用基礎架構。它為構建物聯網解決方案提供了更簡單、更敏捷的模型。</p><p><em>業務流程管理平台即服務（bpmPaaS）</em>：一個完整的預集成業務流程管理平台，託管在雲端並作為服務交付。它被用於開發和執行整個企業的業務流程和以工作流程為中心的應用程序。例如 Pega cloud 和 OpenText Cordys cloud。</p><p>PaaS 的一些基本特徵：</p><ul><li>在同一集成開發環境中開發、測試、部署、託管和維護應用程序的服務</li><li>多租户架構，即多個併發用户使用同樣的開發程序</li><li>部署軟件的內置可擴展性，包括負載平衡和故障轉移</li><li>與異構平台和系統的集成</li><li>支持開發團隊的協作</li><li>包含處理帳單和管理訂閲的工具</li></ul><h3 id="主要的開源-paas" tabindex="-1">主要的開源 PaaS <a class="header-anchor" href="#主要的開源-paas" aria-label="Permalink to “主要的開源 PaaS”">​</a></h3><p>在選擇 PaaS 之前，企業主要考慮關注以下幾點：</p><ul><li>部署靈活性</li><li>操作簡便性</li><li>應用堆棧的選擇</li><li>語言、資料庫和框架支持</li><li>規模的可擴展性</li><li>服務質量（QoS）</li><li>開發和運營的工具</li><li>它有多適合你的業務</li></ul><p>現在讓我們快速瀏覽下流行的開源 PaaS。</p><p><em>Cloud Foundry</em>：提供了多種雲的選擇、開發者框架和應用服務。Cloud Foundry 使構建、測試、部署和擴展應用程序變得更快、更容易。</p><p>它有不同的發行版本，其中比較流行的是 Pivotal 和 IBM。它包含應用<ruby>運行時<rt>runtime</rt></ruby>和容器運行時。在 Pivotal 上包含有應用服務和容器服務。</p><p><em>OpenShift</em>：紅帽的雲計算 PaaS 產品。這是一個雲端的應用平台，應用開發者和團隊可以在這裏構建、測試、部署和運行他們的應用程序。</p><p><em>Cloudify</em>：在開放的原則下開發和設計，用以推動 IT 轉型革命。它使組織能夠在其上設計、建立和提供各種商業應用和網絡服務。Cloudify 的最新版本為 4.3，它包含了先進的安全、控制和<ruby>真自服務<rt>true self-service</rt></ruby>等增強功能。Cloudify 4.3 還為 Kubernetes 容器編排引入了全新的概念。</p><div class="table-wrap"><table><thead><tr><th style="text-align:left;">功能</th><th style="text-align:left;">Cloud Foundry</th><th style="text-align:left;">Cloudify</th><th style="text-align:left;">OpenShift</th></tr></thead><tbody><tr><td style="text-align:left;">核心功能</td><td style="text-align:left;">Cloud controller</td><td style="text-align:left;">Manager</td><td style="text-align:left;">Broker</td></tr><tr><td style="text-align:left;">提供第三方資料庫服務</td><td style="text-align:left;">Service broker</td><td style="text-align:left;">Agent</td><td style="text-align:left;">Cartridge</td></tr><tr><td style="text-align:left;">傳入流量的路由</td><td style="text-align:left;">Router</td><td style="text-align:left;">Manager</td><td style="text-align:left;">REST API</td></tr><tr><td style="text-align:left;">查詢應用程序的狀態</td><td style="text-align:left;">Cloud controller</td><td style="text-align:left;">CLI client</td><td style="text-align:left;">Broker</td></tr><tr><td style="text-align:left;">消息傳遞</td><td style="text-align:left;">Message bus</td><td style="text-align:left;">Manager</td><td style="text-align:left;">Broker</td></tr><tr><td style="text-align:left;">應用實例管理</td><td style="text-align:left;">Droplet execution agent</td><td style="text-align:left;">Agent</td><td style="text-align:left;">Node</td></tr><tr><td style="text-align:left;">應用程序狀態管理</td><td style="text-align:left;">Health manager</td><td style="text-align:left;">Manager</td><td style="text-align:left;">Broker</td></tr><tr><td style="text-align:left;">Broker</td><td style="text-align:left;">Warden</td><td style="text-align:left;">Agent</td><td style="text-align:left;">Gear</td></tr><tr><td style="text-align:left;">用户請求的負載平衡</td><td style="text-align:left;">Droplet execution agent</td><td style="text-align:left;">Manager</td><td style="text-align:left;">Broker</td></tr><tr><td style="text-align:left;">框架提供者</td><td style="text-align:left;">Blob store</td><td style="text-align:left;">Agent</td><td style="text-align:left;">Cartridge</td></tr><tr><td style="text-align:left;">技術</td><td style="text-align:left;"></td><td style="text-align:left;"></td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;">語言</td><td style="text-align:left;">Java, Ruby, Scala, Node.js, Groovy, Grails, PHP, Go, Python</td><td style="text-align:left;">Java, PHP, Ruby</td><td style="text-align:left;">Java, Ruby, Node.js, PHP, Python, Perl, JavaScript</td></tr><tr><td style="text-align:left;">資料庫</td><td style="text-align:left;">MongoDB，MySQL</td><td style="text-align:left;"></td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;">MongoDB、MySQL、PostgreSQL</td><td style="text-align:left;">MySQL、MongoDB</td><td style="text-align:left;">MongoDB、MySQL、PostgreSQL</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;">框架</td><td style="text-align:left;">Spring, Rails, Grails, Play Sinatra</td><td style="text-align:left;">JavaScript, Node.js</td><td style="text-align:left;">Rails, Flask, Django, Drupal, Vertx</td></tr><tr><td style="text-align:left;">水平擴展</td><td style="text-align:left;">是</td><td style="text-align:left;">是</td><td style="text-align:left;">是</td></tr><tr><td style="text-align:left;">垂直擴展</td><td style="text-align:left;">是</td><td style="text-align:left;">否</td><td style="text-align:left;">是</td></tr><tr><td style="text-align:left;">彈性伸縮</td><td style="text-align:left;">是</td><td style="text-align:left;">是</td><td style="text-align:left;">是</td></tr></tbody></table></div><p>表 1 列出了 Cloud Foundry、Cloudify 和 OpenShift 的基本功能及其對應的架構組件。以上完全基於個人觀點，所支持的功能的真實需求應與雲供應商進行驗證。</p><p>從行業統計數據中，我們可以清楚地看出 PaaS 的使用率正在迅速上升。PaaS 使企業應用程序可以是<ruby>雲無關<rt>cloud-agnostic</rt></ruby>的，它們可以在任何雲平台上運行——無論是公共的還是私有的。這意味着一個在亞馬遜的 AWS 上開發的應用可以很容易地移植到微軟 Azure、VMWare vSphere、Red Hat RHEV 等等其他平台。</p><p>當多個開發人員共同參與一個開發項目，或外部用户需要與開發過程協作時，PaaS 是很有用的。因此，PaaS 尤其適合於敏捷開發，因為它降低了圍繞軟件快速開發和迭代的難度。</p><h3 id="鳴謝" tabindex="-1">鳴謝 <a class="header-anchor" href="#鳴謝" aria-label="Permalink to “鳴謝”">​</a></h3><p>作者感謝 Kiran M.R. 和 Wipro 有限公司的數字架構實踐 Raju Alluri 為本文提供的支持。</p><hr>',37)),d("p",null,[t[1]||(t[1]=e("via: ",-1)),a(l,{href:"https://www.opensourceforu.com/2022/09/why-enterprises-should-opt-for-platform-as-a-service/"},{default:r(()=>[...t[0]||(t[0]=[e("https://www.opensourceforu.com/2022/09/why-enterprises-should-opt-for-platform-as-a-service/",-1)])]),_:1})]),d("p",null,[t[6]||(t[6]=e("作者：",-1)),a(l,{href:"https://www.opensourceforu.com/author/gopalakrishna-behara/"},{default:r(()=>[...t[2]||(t[2]=[e("Gopala Krishna Behara",-1)])]),_:1}),t[7]||(t[7]=e(" 選題：",-1)),a(l,{href:"https://github.com/lkxed"},{default:r(()=>[...t[3]||(t[3]=[e("lkxed",-1)])]),_:1}),t[8]||(t[8]=e(" 譯者：",-1)),a(l,{href:"https://github.com/onionstalgia"},{default:r(()=>[...t[4]||(t[4]=[e("onionstalgia",-1)])]),_:1}),t[9]||(t[9]=e(" 校對：",-1)),a(l,{href:"https://github.com/wxy"},{default:r(()=>[...t[5]||(t[5]=[e("wxy",-1)])]),_:1})]),d("p",null,[t[12]||(t[12]=e("本文由 ",-1)),a(l,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[10]||(t[10]=[e("LCTT",-1)])]),_:1}),t[13]||(t[13]=e(" 原創編譯，",-1)),a(l,{href:"https://linux.cn/"},{default:r(()=>[...t[11]||(t[11]=[e("Linux中國",-1)])]),_:1}),t[14]||(t[14]=e(" 榮譽推出",-1))])])}const C=i(p,[["render",y]]);export{h as __pageData,C as default};
